    public static function addLAST_OBSERVED(FlatBufferBuilder $builder, $LAST_OBSERVED)
    {
        $builder->addOffsetX(31, $LAST_OBSERVED, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param uint
     * @return void
     */
    public static function addOBSERVATION_COUNT(FlatBufferBuilder $builder, $OBSERVATION_COUNT)
    {
        $builder->addUintX(32, $OBSERVATION_COUNT, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param VectorOffset
     * @return void
     */
    public static function addSOURCES(FlatBufferBuilder $builder, $SOURCES)
    {
        $builder->addOffsetX(33, $SOURCES, 0);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param array offset array
     * @return int vector offset
     */
    public static function createSOURCESVector(FlatBufferBuilder $builder, array $data)
    {
        $builder->startVector(4, count($data), 4);
        for ($i = count($data) - 1; $i >= 0; $i--) {
            $builder->putOffset($data[$i]);
        }
        return $builder->endVector();
    }

    /**
     * @param FlatBufferBuilder $builder
     * @param int $numElems
     * @return void
     */
    public static function startSOURCESVector(FlatBufferBuilder $builder, $numElems)
    {
        $builder->startVector(4, $numElems, 4);
    }

    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endSTX(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // ID
        $builder->required($o, 70);  // SOURCES
        return $o;
    }

    public static function finishSTXBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$STX");
    }
}
